import{_ as t,o as s,c as i,ag as a}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Orchestration Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/orchestration.md","filePath":"architecture/orchestration.md"}'),n={name:"architecture/orchestration.md"};function o(l,e,r,p,c,d){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="orchestration-pipeline" tabindex="-1">Orchestration Pipeline <a class="header-anchor" href="#orchestration-pipeline" aria-label="Permalink to &quot;Orchestration Pipeline&quot;">​</a></h1><p>The orchestration pipeline is implemented in <code>AgentOrchestrationService</code> — the central brain of the system. It uses Azure OpenAI for every decision point and <code>Microsoft.Extensions.AI</code> for tool invocation.</p><h2 id="pipeline-stages" tabindex="-1">Pipeline Stages <a class="header-anchor" href="#pipeline-stages" aria-label="Permalink to &quot;Pipeline Stages&quot;">​</a></h2><h3 id="stage-1-azure-context-resolution" tabindex="-1">Stage 1: Azure Context Resolution <a class="header-anchor" href="#stage-1-azure-context-resolution" aria-label="Permalink to &quot;Stage 1: Azure Context Resolution&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ResolveAzureContextAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prompt, existingContext, conversationHistory)</span></span></code></pre></div><p>The LLM extracts Azure resource identifiers from the user&#39;s prompt and conversation history:</p><ul><li><strong>Subscription IDs</strong> (single or multiple)</li><li><strong>Resource groups</strong> (single or multiple)</li><li><strong>Resource names</strong> (single or multiple)</li><li><strong>Resource type</strong> (e.g., <code>Microsoft.Compute/virtualMachines</code>)</li><li><strong>Resource ID</strong> (full ARM resource path)</li><li><strong>Region</strong> (e.g., <code>eastus</code>)</li></ul><p><strong>Key behaviors:</strong></p><ul><li>If <code>existingContext</code> already has scope (<code>HasScope == true</code>), it is reused without an LLM call</li><li>The LLM is explicitly instructed to <strong>extract, never invent</strong> identifiers</li><li>Both singular fields (<code>SubscriptionId</code>) and plural fields (<code>SubscriptionIds</code>) are supported</li><li>JSON code fences in LLM output are automatically stripped</li></ul><p><strong>Output:</strong> <code>AzureContext</code> object with de-duplicated scope fields.</p><h3 id="stage-2-intent-classification" tabindex="-1">Stage 2: Intent Classification <a class="header-anchor" href="#stage-2-intent-classification" aria-label="Permalink to &quot;Stage 2: Intent Classification&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ClassifyIntentAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prompt, conversationHistory, skillDefinitions)</span></span></code></pre></div><p>The LLM categorizes the user&#39;s request into one of three intents:</p><table tabindex="0"><thead><tr><th>Intent</th><th>Description</th><th>Pipeline Path</th></tr></thead><tbody><tr><td><code>Informational</code></td><td>General Azure knowledge question</td><td>Direct LLM answer</td></tr><tr><td><code>ActionRequired</code></td><td>Requires live Azure data via skills</td><td>Task decomposition → skill execution</td></tr><tr><td><code>Unknown</code></td><td>Ambiguous or unsupported</td><td>Error response</td></tr></tbody></table><p><strong>Key behaviors:</strong></p><ul><li>The LLM receives the list of available skills as context</li><li>Follow-up messages in a conversation are treated as continuations of prior intent, not new <code>Unknown</code> inputs</li><li>Returns structured JSON: <code>{ &quot;intent&quot;: &quot;...&quot;, &quot;reasoning&quot;: &quot;...&quot; }</code></li></ul><h3 id="stage-3-direct-answer-informational-path" tabindex="-1">Stage 3: Direct Answer (Informational path) <a class="header-anchor" href="#stage-3-direct-answer-informational-path" aria-label="Permalink to &quot;Stage 3: Direct Answer (Informational path)&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AnswerDirectlyAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prompt, azureContext, conversationHistory)</span></span></code></pre></div><p>For informational queries, the LLM answers directly using its knowledge and the conversation context. The system prompt positions it as an expert across:</p><ul><li>Reliability &amp; resiliency</li><li>Cost optimization</li><li>Security best practices</li><li>Operational excellence</li></ul><p>No tools are invoked for this path.</p><h3 id="stage-4-task-decomposition-actionrequired-path" tabindex="-1">Stage 4: Task Decomposition (ActionRequired path) <a class="header-anchor" href="#stage-4-task-decomposition-actionrequired-path" aria-label="Permalink to &quot;Stage 4: Task Decomposition (ActionRequired path)&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DecomposeTasksAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prompt, azureContext, conversationHistory, skillDefinitions)</span></span></code></pre></div><p>The LLM breaks down the user&#39;s request into a task plan — a JSON array of tasks, each assigned to exactly one skill:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;task&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Retrieve cost optimization recommendations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;skillName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CostOptimizationSkill&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dependsOn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;task&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Analyze resiliency posture of identified resources&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;skillName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ResiliencySkill&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dependsOn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><strong>Key behaviors:</strong></p><ul><li>Each task is assigned to exactly one skill from the catalog</li><li><code>dependsOn</code> is an array of 0-based task indices (forming a DAG)</li><li>The LLM retries up to 2 times on JSON parse failure</li><li>Tasks are validated against known skills and topologically sorted</li></ul><h3 id="stage-5-skill-prompt-generation" tabindex="-1">Stage 5: Skill Prompt Generation <a class="header-anchor" href="#stage-5-skill-prompt-generation" aria-label="Permalink to &quot;Stage 5: Skill Prompt Generation&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GenerateSkillPromptAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(task, skillDefinition, azureContext, upstreamOutputs, conversationHistory)</span></span></code></pre></div><p>For each task, a skill-specific prompt is constructed containing:</p><ol><li>The task description</li><li>Skill&#39;s <code>SystemPrompt</code> and <code>ExpectedInput</code></li><li>Azure context (subscription, resource group, etc.)</li><li>Outputs from upstream dependency tasks (context chaining)</li><li>Relevant conversation history</li></ol><h3 id="stage-6-skill-execution" tabindex="-1">Stage 6: Skill Execution <a class="header-anchor" href="#stage-6-skill-execution" aria-label="Permalink to &quot;Stage 6: Skill Execution&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ExecuteSkillAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(skillDefinition, prompt, accessToken)</span></span></code></pre></div><p>Each skill executes as a self-contained LLM conversation with tool access:</p><ol><li><strong>Tool resolution</strong> — parses tool names (<code>ClassName-MethodName</code>), finds method via reflection, wraps with <code>AIFunctionFactory</code></li><li><strong>Access token injection</strong> — calls <code>SetAccessToken()</code> on each tool instance so they can make authenticated ARM/ARG calls</li><li><strong>Chat completion</strong> — creates an <code>AzureOpenAI</code> chat client with <code>FunctionInvocation</code> middleware</li><li><strong>Tool loop</strong> — the LLM calls tools as needed; the middleware automatically invokes them and feeds results back</li><li><strong>Response parsing</strong> — the structured response is extracted and wrapped in <code>AdvisorAgentResponse</code></li></ol><p><strong>Execution parameters per skill:</strong></p><ul><li><code>ModelName</code> — defaults to <code>gpt-4o</code></li><li><code>Temperature</code> — <code>0.0</code> for deterministic output</li><li><code>Timeout</code> — <code>120s</code> default per skill</li></ul><h2 id="conversation-history-integration" tabindex="-1">Conversation History Integration <a class="header-anchor" href="#conversation-history-integration" aria-label="Permalink to &quot;Conversation History Integration&quot;">​</a></h2><p>All LLM calls (context resolution, intent classification, task decomposition, direct answer, skill execution) receive conversation history via <code>BuildMessagesWithHistory()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[System Prompt]</span></span>
<span class="line"><span>[Turn 1: User prompt] → [Turn 1: Assistant response (truncated to 1000 chars)]</span></span>
<span class="line"><span>[Turn 2: User prompt] → [Turn 2: Assistant response (truncated to 1000 chars)]</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[Current User prompt]</span></span></code></pre></div><p>This enables context-aware follow-up questions like:</p><ul><li>&quot;What about subscription B?&quot; (references prior subscription discussion)</li><li>&quot;Can you break that down by resource group?&quot; (references prior analysis)</li></ul><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Behavior</th></tr></thead><tbody><tr><td>LLM returns invalid JSON</td><td>Retry up to 2 times; fall back to raw text</td></tr><tr><td>Unknown skill in task plan</td><td>Filtered out by <code>PlanValidator.RemoveUnknownSkills()</code></td></tr><tr><td>Cycle in task dependencies</td><td><code>TopologicalSort()</code> throws; orchestrator falls back to sequential execution</td></tr><tr><td>Skill execution timeout</td><td>120s default; returns timeout error</td></tr><tr><td>Tool method not found</td><td>Logged as warning; missing tool skipped</td></tr><tr><td>ARM API failure</td><td>Exception propagated; skill returns failure response</td></tr></tbody></table>`,44)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
